#!/usr/bin/env node
import { readFile } from 'node:fs/promises';
import { parseCsv } from '../src/csv.js';
import { formatSummary, summarise } from '../src/summarise.js';

const USAGE = 'usage: colsummary <file.csv> --column <name>';

function parseArgs(args) {
  let file;
  let column;
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === '--column') {
      column = args[i + 1];
      if (column === undefined) throw new Error('--column needs a name');
      i += 1;
    } else if (args[i].startsWith('--')) throw new Error(`unknown option ${args[i]}`);
    else if (file === undefined) file = args[i];
    else throw new Error(`unexpected argument ${args[i]}`);
  }
  if (file === undefined) throw new Error('no file named');
  if (column === undefined) throw new Error('no --column given');
  return { file, column };
}

async function main(args) {
  let options;
  try {
    options = parseArgs(args);
  } catch (e) {
    process.stderr.write(`colsummary: ${e.message}\n${USAGE}\n`);
    return 1;
  }
  let text;
  try {
    text = await readFile(options.file, 'utf8');
  } catch (e) {
    process.stderr.write(`colsummary: cannot read ${options.file}: ${e.code === 'ENOENT' ? 'no such file' : e.message}\n`);
    return 2;
  }
  try {
    process.stdout.write(formatSummary(summarise(parseCsv(text), options.column)));
    return 0;
  } catch (e) {
    process.stderr.write(`colsummary: ${e.message}\n`);
    return 1;
  }
}

process.exitCode = await main(process.argv.slice(2));

// RFC 4180: fields are separated by commas and records by CRLF or LF; a field may be enclosed in double quotes,
// and inside one a comma or a line break is part of the field and a doubled quote is one quote.
export function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (quoted) {
      if (ch !== '"') field += ch;
      else if (text[i + 1] === '"') { field += '"'; i += 1; }
      else quoted = false;
    } else if (ch === '"' && field === '') quoted = true;
    else if (ch === ',') { row.push(field); field = ''; }
    else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && text[i + 1] === '\n') i += 1;
      row.push(field); rows.push(row); row = []; field = '';
    } else field += ch;
  }
  if (quoted) throw new Error('unterminated quoted field');
  if (field !== '' || row.length > 0) { row.push(field); rows.push(row); }
  return rows;
}

const NUMBER = /^-?\d+(\.\d+)?$/;

// The summary of the column the first row names `column`: a blank cell is missing, any other must be a decimal number.
export function summarise(rows, column) {
  const [header = [], ...records] = rows;
  const index = header.indexOf(column);
  if (index === -1) throw new Error(`no column named "${column}"`);
  const values = [];
  let missing = 0;
  records.forEach((record, i) => {
    const cell = (record[index] ?? '').trim();
    if (cell === '') { missing += 1; return; }
    if (!NUMBER.test(cell)) throw new Error(`row ${i + 2}: "${cell}" in column "${column}" is not a number`);
    values.push(Number(cell));
  });
  if (values.length === 0) return { count: 0, missing, min: 'none', max: 'none', mean: 'none' };
  const sum = values.reduce((a, b) => a + b, 0);
  return { count: values.length, missing, min: Math.min(...values), max: Math.max(...values), mean: (sum / values.length).toFixed(2) };
}

export function formatSummary(s) {
  return ['count', 'missing', 'min', 'max', 'mean'].map((k) => `${k} ${s[k]}`).join('\n') + '\n';
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';

const run = (...args) => spawnSync(process.execPath, ['bin/colsummary.js', ...args], { encoding: 'utf8' });

test('prints the five lines for a column of the fixture (R1)', () => {
  const r = run('test/fixtures/readings.csv', '--column', 'reading');
  assert.equal(r.status, 0);
  assert.equal(r.stdout, 'count 3\nmissing 1\nmin 7\nmax 17.5\nmean 12.33\n');
  assert.equal(r.stderr, '');
});

test('an unreadable file exits 2 with a message and prints nothing (R5)', () => {
  const r = run('test/fixtures/absent.csv', '--column', 'reading');
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
  assert.match(r.stderr, /^colsummary: cannot read test\/fixtures\/absent\.csv/);
});

test('a column not in the file exits 1 with a message and prints nothing (R6)', () => {
  const r = run('test/fixtures/readings.csv', '--column', 'depth');
  assert.equal(r.status, 1);
  assert.equal(r.stdout, '');
  assert.match(r.stderr, /no column named "depth"/);
});

test('a bad argument exits 1 with the usage line and prints nothing (R6)', () => {
  const r = run('test/fixtures/readings.csv');
  assert.equal(r.status, 1);
  assert.equal(r.stdout, '');
  assert.match(r.stderr, /usage: colsummary <file\.csv> --column <name>/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv } from '../src/csv.js';

test('splits fields on commas and records on LF and CRLF (R2)', () => {
  assert.deepEqual(parseCsv('a,b\n1,2\r\n3,4\n'), [['a', 'b'], ['1', '2'], ['3', '4']]);
});

test('a quoted field may hold commas (R2)', () => {
  assert.deepEqual(parseCsv('site,note\nSouth,"pump off, no reading"\n'), [['site', 'note'], ['South', 'pump off, no reading']]);
});

test('a doubled quote inside a quoted field is one quote (R2)', () => {
  assert.deepEqual(parseCsv('note\n"checked ""twice"""\n'), [['note'], ['checked "twice"']]);
});

test('an unterminated quoted field is refused (R2)', () => {
  assert.throws(() => parseCsv('note\n"open\n'), /unterminated quoted field/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { formatSummary, summarise } from '../src/summarise.js';

const rows = [['site', 'reading'], ['North', '12.5'], ['South', ''], ['East', '7'], ['West', '17.5']];

test('count, min and max of a numeric column (R1)', () => {
  const s = summarise(rows, 'reading');
  assert.equal(s.count, 3);
  assert.equal(s.min, 7);
  assert.equal(s.max, 17.5);
});

test('the mean is rounded to two decimal places (R1)', () => {
  assert.equal(summarise(rows, 'reading').mean, '12.33');
});

test('blank cells are counted as missing (R3)', () => {
  assert.equal(summarise(rows, 'reading').missing, 1);
});

test('min, max and mean are none when no cell holds a value (R4)', () => {
  assert.equal(formatSummary(summarise([['reading'], [''], ['  ']], 'reading')), 'count 0\nmissing 2\nmin none\nmax none\nmean none\n');
});

test('a column not in the first row is refused (R6)', () => {
  assert.throws(() => summarise(rows, 'depth'), /no column named "depth"/);
});

test('a cell that is not a decimal number is refused, naming its row (R6)', () => {
  assert.throws(() => summarise([['reading'], ['12'], ['n/a']], 'reading'), /row 3: "n\/a" in column "reading" is not a number/);
});
